// Startup:
services.AddZeroWeb(options => options.RoutePrefix = "/api");
services.AddZeroMessaging();

// Endpoints are closed by default, so authorization is part of the minimal application.
// Opt out with options.RequireAuthorizationByDefault = false if there is no authentication
// anywhere; MapZeroEndpoints refuses to map rather than let every route 500 at runtime.
services.AddAuthorization();
services.AddModules(new Module());

app.UseAuthentication();
app.UseAuthorization();
app.MapZeroEndpoints();

// The handler never mentions HTTP. A NotFound error becomes 404, a Conflict 409.
// A body must be application/json or a +json suffix, or the answer is 415.
